import math

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    # Define a helper function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    # Check if the number is less than 100
    if a < 100:
        # Find all prime factors of the number
        factors = set()
        for i in range(2, a + 1):
            while a % i == 0:
                factors.add(i)
                a //= i
        # Check if the number of prime factors is exactly 3
        return len(factors) == 3 and all(is_prime(factor) for factor in factors)
    else:
        return False
